import { DRAFT_TOOLS } from './draftTools.server'
import { READ_TOOLS } from './readTools.server'
import { registerTools, type AgentTool } from './tools.server'

/** Every tool the agent interface offers, in tools/list order. */
export const AGENT_TOOLS: readonly AgentTool[] = [...READ_TOOLS, ...DRAFT_TOOLS]

export const SERVER_INFO = { name: 'ifj26-table-maker', version: '1.0.0' }

const INSTRUCTIONS = `IFJ26 Table Maker: helps design the LL(1) table and the precedence table of the IFJ26 compiler.
A project holds four parts: the definition (N, T, S), the grammar rules (P, from which the LL table is computed), the precedence table (relations < = > between precedence terminals and $) and the reduction rules (what the precedence simulation reduces by).
Read tools take a target: a project ({"kind":"project","id":"…"}), a draft ({"kind":"draft","id":"…"}) or a snapshot of either ({"kind":"snapshot","id":12}). Start with list_projects.
An agent never changes a project. To propose changes, create a draft (create_draft) – an editable copy of the project's four parts – or resume an open one (list_drafts), and edit it with set_definition, set_grammar_rules, set_reduction_rules, set_prec_terminals, set_relation and clear_relations. Every edit returns the draft's new revision and its fresh problems. Pass expectedRevision on whole-text edits so you never overwrite a part someone else changed meanwhile.
The human reviews a draft and adopts the parts they want; agents cannot adopt. Discard a dead-end draft with discard_draft. Ended (adopted or discarded) drafts and snapshots are read-only. Export naming and simulation inputs belong to the project and are read-only for agents.`

// Same rule as the server functions (src/start.ts): a browser page from another site (or another port / *.ts.net host,
// which is 'same-site') must not drive the agent interface. Without Fetch Metadata an Origin, when sent, must match.
// Agents and curl send neither and are served (tailnet trust, ADR 0001).
function isForeignBrowserRequest(request: Request) {
  const site = request.headers.get('sec-fetch-site')
  if (site) return site !== 'same-origin' && site !== 'none'
  const origin = request.headers.get('origin')
  return origin !== null && origin !== new URL(request.url).origin
}

const forbidden = () =>
  Response.json(
    { jsonrpc: '2.0', id: null, error: { code: -32000, message: 'Cross-site requests are not allowed' } },
    { status: 403 },
  )

// Stateless: no server-initiated stream (GET) and no session to end (DELETE).
const methodNotAllowed = () =>
  Response.json(
    { jsonrpc: '2.0', id: null, error: { code: -32000, message: 'Method not allowed; this MCP endpoint is stateless and accepts POST only' } },
    { status: 405, headers: { allow: 'POST' } },
  )

export async function handleAgentRequest(request: Request, store: ProjectStore): Promise<Response> {
  if (isForeignBrowserRequest(request)) return forbidden()
  if (request.method !== 'POST') return methodNotAllowed()
  const server = new McpServer(SERVER_INFO, { capabilities: { tools: {} }, instructions: INSTRUCTIONS })
  registerTools(server, AGENT_TOOLS, { store })
  const transport = new WebStandardStreamableHTTPServerTransport({ sessionIdGenerator: undefined, enableJsonResponse: true })
  await server.connect(transport)
  return transport.handleRequest(request)
}
